function extract($, ctx) {
  const items = [];

  // Each section that contains a list of menu items
  $('section.page-section:has(.user-items-list)').each((_, secEl) => {
    const $sec = $(secEl);
    // Section title (e.g., PLANTEBASERT, BURGERE, …)
    const sectionTitle = cleanText($sec.find('.list-section-title strong').text()) || null;

    // Individual menu items inside this section
    $sec.find('.user-items-list-simple > li.list-item').each((_, itmEl) => {
      const $itm = $(itmEl);

      // Dish name
      const nameRaw = $itm.find('.list-item-content__title').text();
      const name = cleanText(nameRaw);
      if (!name) return; // skip empty names

      // Description: all <p> that do NOT hold the price (price is inside <strong>)
      const descTexts = $itm
        .find('.list-item-content__description p:not(:has(strong))')
        .map((_, p) => cleanText($(p).text()))
        .get()
        .join(' ');
      const description = descTexts || null;

      // Price: first <strong> inside the description block
      const priceRaw = $itm.find('.list-item-content__description p strong').text();
      const price = parsePrice(priceRaw);

      items.push({ section: sectionTitle, name, description, price });
    });
  });

  // Deduplicate exact duplicates (e.g., mobile/desktop copies)
  const seen = new Set();
  const deduped = items.filter(it => {
    const key = JSON.stringify(it);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  return deduped;
}
